    if(($defined-join'|')-ne($wantedDefined-join'|')){throw "S6006 object/export symbol conflict for module $($module.module)."};if(($undefined-join'|')-ne($wantedUndefined-join'|')){throw "S6006 object relocation/import symbol conflict for module $($module.module)."};foreach($symbol in $wantedUndefined){if($relocations1-notmatch[regex]::Escape($symbol)){throw "S6006 missing relocation for $symbol."}}
    $hash1=Hash-File $object1;$hash2=Hash-File $object2;$evidenceHash=Hash-Text ($module.assemblyHash+'|'+(Hash-Text $symbols1)+'|'+(Hash-Text $relocations1)+'|'+(Hash-Text $disassembly1)+'|'+$plan.symbolTableHash+'|'+$plan.effectsHash)
    $moduleReports[[string]$module.module]=[ordered]@{assemblyHash=$module.assemblyHash;objectHash=$hash1;reproducibleObjectHash=if($hash1-eq$hash2){$hash1}else{$null};symbolsHash=Hash-Text $symbols1;relocationsHash=Hash-Text $relocations1;disassemblyHash=Hash-Text $disassembly1;evidenceHash=$evidenceHash;definedSymbols=$defined;undefinedSymbols=$undefined;normalizedEvidenceIdentical=$true;objectByteIdentical=$hash1-eq$hash2;objectEmitted=$true;executableLinked=$false}
    $objects1+=$object1;$objects2+=$object2;$expectedExports+=$wantedDefined
  }
  $stdlibObjects1=Get-ChildItem -LiteralPath (Join-Path $stdlibOutput 'run-1') -File -Recurse -Filter '*.obj'|Sort-Object FullName|ForEach-Object FullName;$stdlibObjects2=Get-ChildItem -LiteralPath (Join-Path $stdlibOutput 'run-2') -File -Recurse -Filter '*.obj'|Sort-Object FullName|ForEach-Object FullName
  $linked1=Join-Path $run1 'stellar-package.inspect-only.dll';$linked2=Join-Path $run2 'stellar-package.inspect-only.dll';$exports=@($expectedExports|Sort-Object -Unique|ForEach-Object{'/EXPORT:'+$_});$fixed=@('/nologo','/dll','/noentry','/nodefaultlib','/machine:x64','/incremental:no','/opt:ref','/opt:icf','/Brepro')
